    # diagonal from its pair, while retaining the original marked cells.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Detect the non-background colors; the most frequent is the background.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    colors = [v for v in counts if v != bg]

    # Rays continue along diagonal directions where two same-colored cells
    # establish the direction, extending through background to the edge.
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                if (r + dr, c + dc) not in pts:
                    continue
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
    return out
